const nums = [2, 3];
nums.unshift(1); // [1, 2, 3]
nums.shift();    // вернёт 1, массив [2, 3]

const fruits = ["яблоко", "груша"];
fruits.includes("груша"); // true
fruits.includes("слива"); // false

const nums = [1, 2, 3, 4];
nums.splice(1, 2); // удалил [2, 3]
// nums теперь [1, 4]

const nums = [1, 2, 3];
const doubled = nums.map((n) => n * 2);
// doubled = [2, 4, 6]

const nums = [1, 2, 3, 4];
const even = nums.filter((n) => n % 2 === 0);
// even = [2, 4]

const nums = [5, 12, 8];
nums.find((n) => n > 10); // 12
nums.find((n) => n > 100); // undefined

const nums = [2, 4, 6];
const sum = nums.reduce((total, n) => total + n, 0);
// sum = 12

const a = [1, 2];
const b = a;     // та же самая коробка
const c = [...a]; // отдельная копия
b.push(3);
// a = [1, 2, 3], c = [1, 2]
